#include <bits/stdc++.h>
using namespace std;

#define int long long

signed main() {
	// your code goes here
    int t; cin >> t;
    while (t--){
        int n; cin >> n;
        vector<int> a(3*n+1);
        for (int i = 1; i <= 3*n; i++) cin >> a[i];
        sort(a.begin()+1,a.end());
        reverse(a.begin()+1,a.end());
        vector<int> pf(3*n+1);
        for (int i = 1; i <= 3*n; i++) pf[i] = pf[i-1] + a[i];
        int ans = 0;
        
        for (int aa = 0; aa <= n; aa++){
            // assume c = n-a right now 
            // current : 6xa + 3x(n-a)
            // lets binary search on b
            // let current b be x
            // then c is n-a-x
            int cur = 0;
            for (int bit = 30; bit >= 0; bit--){
                int newcur = cur + (1 << bit);
                if (newcur > n-aa) continue;
                // see if its good to go from newcur-1 to newcur
                int x = newcur-1;
                int diff = a[aa+2*x+1] + a[aa+2*x+2]- 3 *a[3*n-2*aa-x];
                if (diff > 0) cur = newcur;
            }
            // extend till cur 
            int res = 2 * pf[aa] + pf[aa + 2*cur] + 3*pf[aa + 2*cur + 3*(n-aa-cur)];
            ans = max(ans,res);
        }
        
        cout << ans << '\n';
    }
}
